function h($v): string { return htmlspecialchars((string)$v, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
function money($v): string { return 'Rs. '.number_format((float)$v, 0); }
function db(): ?PDO { global $config; static $pdo=null; if($pdo) return $pdo; try { $d=$config['db']; $pdo=new PDO("mysql:host={$d['host']};dbname={$d['name']};charset={$d['charset']}",$d['user'],$d['pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]); return $pdo; } catch(Throwable $e) { return null; } }
function products(string $where='', array $params=[], int $limit=30): array { $p=db(); if(!$p)return []; $sql='SELECT p.*,b.name brand,c.name category FROM products p LEFT JOIN brands b ON b.id=p.brand_id LEFT JOIN categories c ON c.id=p.category_id '.$where.' LIMIT '.(int)$limit; $q=$p->prepare($sql);$q->execute($params);return $q->fetchAll(); }
function itemById($id): ?array { $p=db(); if(!$p)return null; $q=$p->prepare('SELECT * FROM products WHERE id=?');$q->execute([(int)$id]);return $q->fetch()?:null; }
function csrf(): string { if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));return $_SESSION['csrf']; }
function flash(string $msg): void { $_SESSION['flash']=$msg; }
