 if($action==='register'){ $p=db();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pw=(string)($_POST['password']??'');if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pw)<10){flash('Enter a valid name/email and password (10+ characters).');}else{try{$q=$p->prepare('INSERT INTO users(name,email,password_hash,phone) VALUES(?,?,?,?)');$q->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT),trim($_POST['phone']??'')]);session_regenerate_id(true);$_SESSION['user_id']=(int)$p->lastInsertId();$_SESSION['user_name']=$name;$_SESSION['role']='customer';header('Location: ?page=account');exit;}catch(Throwable $e){flash('Could not create account; that email may already be registered.');}} }
