n" placeholder="Description"><?=h($editProduct['description']??'')?></textarea><button class="btn btn-dark">Save product</button></form><div class="table-responsive"><table class="table"><thead><tr><th>Product</th><th>SKU</th><th>Price</th><th>Stock</th><th>Actions</th></tr></thead><tbody><?php foreach($adm->query('SELECT * FROM products ORDER BY id DESC LIMIT 100') as $pr):?><tr><td><?=h($pr['name'])?></td><td><?=h($pr['sku'])?></td><td><?=money($pr['price'])?></td><td><?=$pr['stock']?></td><td><a href="?page=admin&tab=products&edit=<?=$pr['id']?>">Edit</a> <form method="post" style="display:inline"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="admin_product_delete"><input type="hidden" name="id" value="<?=$pr['id']?>"><button class="btn btn-sm btn-outline-danger" onclick="return confirm('Remove product?')">Delete</button></form></td></tr><?php endforeach?></tbody></table></div><?php elseif($tab==='import'):?><h3>Product CSV importer</h3><p>CSV header: name,slug,sku,price,old_price,stock,image_url,short_desc,description. Imports or updates products by slug.</p><form method="post" enctype="multipart/form-data" action="import.php"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="file" name="csv" accept=".csv,text/csv" required><button class="btn btn-dark">Import CSV</button></form><?php else:?><h3>Recent orders</h3><div class="table-responsive"><table class="table"><thead><tr><th>Reference</th><th>Customer</th><th>Total</th><th>Payment</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($adm->query('SELECT * FROM orders ORDER BY id DESC LIMIT 100') as $o):?><tr><td><?=h($o['order_number'])?><small class="d-block"><?=h($o['created_at'])?></small></td><td><?=h($o['name'])?><small class="d-block"><?=h($o['phone'])?></small></td><td><?=money($o['total'])?></td><td><?=h($o['payment_method'])?></td><td><?=h($o['status'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="admin_order"><input type="hidden" name="order_id" value="<?=$o['id']?>"><select name="status"><option>pending</option><option>processing</option><option>completed</option><option>cancelled</option></select><button class="btn btn-sm btn-dark">Save</button></form></td></tr><?php endforeach?></tbody></table></div><?php endif?></div><?php endif?><?php endif?></main>
